import React, { useState } from "react"; // react ke hooks ko import kar rahe hain
import axios from "axios"; //axios ek libarary hai jo HTTP requests ko handle karne ke liye use hoti hai
import { useNavigate } from "react-router-dom"; // ye jab submit button par click karte hain to redirect karta hai home page par uske liya use ata hain

const Signup = () => {
  const navigate = useNavigate(); // ye ek hook hai jo humein navigation ke liye function deta hai

  const [formData, setFormData] = useState({   // useState hook ka use kar rahe hain data ko store karne ke liye
    username: "",
    email: "",
    password: ""
  });

  const handleChange = (e) => {  // matlab ye data ko input field se le raha hai aur formData ko update kar raha hai
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  const handleSubmit = async (e) => {  // ye function form submit hone par call hota hai ,ye data ko backend par bhejta hai by the use of axios
    e.preventDefault();
    try {
      // Adjust your backend API URL if needed
      const res = await axios.post("http://localhost:5000/api/users/signup", { // ye backend par data bhejta hai
        name: formData.username,
        email: formData.email,
        password: formData.password
      });

      console.log(" Signup success:", res.data);
      navigate("/home", { state: { navigation_intent: true } }); //  Redirect to home with intent
    } catch (err) {
      console.error(" Signup failed:", err.response?.data || err.message);
      alert("Signup failed. Please try again.");
    }
  };

  return (
    <div style={{
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      height: "100vh",
      background: "#f6f8fa",
      fontFamily: "'Inter', Arial, sans-serif"
    }}>
      <form onSubmit={handleSubmit} style={{
        background: "#fff",
        padding: "38px 32px 28px 32px",
        borderRadius: "14px",
        boxShadow: "0 6px 32px rgba(0,0,0,0.10)",
        width: "370px",
        fontFamily: "inherit"
      }}>
        <h1 style={{ textAlign: "center", marginBottom: "24px", fontWeight: 700, color: "#222", fontSize: "26px", fontFamily: "inherit" }}>Signup</h1>

        <div style={{ marginBottom: "18px" }}>
          <label htmlFor="username" style={{ display: "block", marginBottom: "7px", fontWeight: 600, color: "#555", fontFamily: "inherit" }}>Username:</label>
          <input
            type="text"
            id="username"
            name="username"
            required
            onChange={handleChange}
            value={formData.username}
            style={{
              width: "100%",
              padding: "12px 14px",
              borderRadius: "8px",
              border: "1.5px solid #e0e0e0",
              fontSize: "15px",
              fontFamily: "inherit",
              outline: "none",
              transition: "border-color 0.2s, box-shadow 0.2s"
            }}
          />
        </div>

        <div style={{ marginBottom: "18px" }}>
          <label htmlFor="email" style={{ display: "block", marginBottom: "7px", fontWeight: 600, color: "#555", fontFamily: "inherit" }}>Email:</label>
          <input
            type="email"
            id="email"
            name="email"
            required
            onChange={handleChange}
            value={formData.email}
            style={{
              width: "100%",
              padding: "12px 14px",
              borderRadius: "8px",
              border: "1.5px solid #e0e0e0",
              fontSize: "15px",
              fontFamily: "inherit",
              outline: "none",
              transition: "border-color 0.2s, box-shadow 0.2s"
            }}
          />
        </div>

        <div style={{ marginBottom: "24px" }}>
          <label htmlFor="password" style={{ display: "block", marginBottom: "7px", fontWeight: 600, color: "#555", fontFamily: "inherit" }}>Password:</label>
          <input
            type="password"
            id="password"
            name="password"
            required
            onChange={handleChange}
            value={formData.password}
            style={{
              width: "100%",
              padding: "12px 14px",
              borderRadius: "8px",
              border: "1.5px solid #e0e0e0",
              fontSize: "15px",
              fontFamily: "inherit",
              outline: "none",
              transition: "border-color 0.2s, box-shadow 0.2s"
            }}
          />
        </div>

        <button type="submit" style={{
          width: "100%",
          padding: "13px",
          background: "linear-gradient(90deg, #3498db 60%, #007bff 100%)",
          color: "white",
          border: "none",
          borderRadius: "8px",
          fontWeight: 700,
          fontSize: "16px",
          cursor: "pointer",
          boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
          transition: "background 0.2s, transform 0.2s"
        }}>
          Signup
        </button>

        <p style={{ marginTop: "18px", textAlign: "center", fontFamily: "inherit" }}>
          Already have an account?{" "}
          <span
            onClick={() => navigate("/login", { state: { navigation_intent: true } })}
            style={{ color: "#007bff", textDecoration: "none", cursor: "pointer", fontWeight: 600 }}
          >
            Login
          </span>
        </p>
      </form>
    </div>
  );
};

export default Signup;
